Object.assign(window.TEM8_DICTIONARY, {"eventually":{"media":{"uk":"media/uk/eventually__gb_1.mp3","us":"media/us/eventually__us_1.mp3"},"oxford":{"phon":"ɪˈventʃuəli","pos":"adverb","senses":[{"en":"at the end of a period of time or a series of events","cn":"最后；终于","ex":{"en":"Our flight eventually left five hours late.","cn":"我们的班机最终晚了五个小时起飞。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"最终;终于","en":"Eventually means in the end, especially after a lot of delays, problems, or arguments.","ex":{"en":"Eventually, the army caught up with him in Latvia","cn":"最终，大部队在拉脱维亚赶上了他。"}},{"pos":"ADV 副词","cn":"最后;结果","en":"Eventually means at the end of a situation or process or as the final result of it.","ex":{"en":"Eventually your child will leave home to lead her own life as a fully independent adult","cn":"最后，你的孩子会离开家，作为一个完全独立的成年人过她自己的生活。"}}]},"examples":[{"en":"She hopes to get a job on the local newspaper and eventually work for ‘The Times’.","cn":"她希望先在当地报社找一份工作，而最后可以到《泰晤士报》工作。"},{"en":"Our flight eventually left five hours late.","cn":"我们的班机最终晚了五个小时起飞。"}]},"everything":{"media":{"uk":"media/uk/everything__gb_1.mp3","us":"media/us/everything__us_1.mp3"},"oxford":{"phon":"ˈevriθɪŋ","pos":"pronoun","senses":[{"en":"all things","cn":"每件事；所有事物；一切","ex":{"en":"Everything had gone.","cn":"一切都过去了。"}},{"en":"the situation now; life generally","cn":"形势；情况；生活","ex":{"en":"Everything in the capital is now quiet.","cn":"目前首都的形势很平静。"}},{"en":"the most important thing","cn":"最重要的东西；最要紧的事情","ex":{"en":"Money isn't everything.","cn":"金钱不是最重要的。"}}]},"collins":{"senses":[{"pos":"PRON-INDEF 不定代词","cn":"所有事物;一切","en":"You use everything to refer to all the objects, actions, activities, or facts in a particular situation.","ex":{"en":"He'd gone to Seattle long after everything else in his life had changed","cn":"他生活中的其他一切都改变了，很久之后他去了西雅图。"}},{"pos":"PRON-INDEF 不定代词","cn":"（可能的）一切事物，所有事物","en":"You use everything to refer to all possible or likely actions, activities, or situations.","ex":{"en":"'This should have been decided long before now.' —'We can't think of everything.'","cn":"“这个在此之前早该决定了。”——“我们不可能考虑得面面俱到。”"}},{"pos":"PRON-INDEF 不定代词","cn":"事态;情况;一切;生活","en":"You use everything to refer to a whole situation or to life in general.","ex":{"en":"She says everything is going smoothly","cn":"她说一切进展顺利。"}},{"pos":"PRON-INDEF 不定代词","cn":"（生命中）最重要的东西，最有价值的东西","en":"If you say that someone or something is everything, you mean you consider them to be the most important thing in your life, or the most important thing that there is.","ex":{"en":"I love him. He is everything to me","cn":"我爱他，他是我的一切。"}},{"pos":"PRON-INDEF 不定代词","cn":"（大多数人渴望的）一切，所有","en":"If you say that someone or something has everything, you mean they have all the things or qualities that most people consider to be desirable.","ex":{"en":"She has everything: beauty, talent, children","cn":"她拥有一切：美貌、才干和子女。"}},{"pos":"PHRASE 短语","cn":"以及其他;等等","en":"You say 'and everything' after mentioning a particular thing or list of things to indicate that they are only examples and that other things are also involved.","ex":{"en":"He had a bed and a fireplace and everything","cn":"他家里有一张床、一个壁炉及其他物品。"}}]},"examples":[{"en":"She seemed to have everything — looks, money, intelligence.","cn":"她似乎什么都有了 — 美貌、金钱和智慧。"},{"en":"Take this bag, and leave everything else to me.","cn":"把这个包拿走，其他所有东西都给我留下。"}]},"every":{"media":{"uk":"media/uk/every__gb_1.mp3","us":"media/us/every__us_1.mp3"},"oxford":{"phon":"ˈevri","pos":"determiner","senses":[{"en":"used with singular nouns to refer to all the members of a group of things or people","cn":"（与单数名词连用，指整体中的）每一个，每个","ex":{"en":"She knows every student in the school.","cn":"她认识学校里的每一个学生。"}},{"en":"used to say how often something happens or is done","cn":"（表示发生的频率）每，每逢，每隔","ex":{"en":"The buses go every 10 minutes.","cn":"公共汽车每隔 10 分钟发一班车。"}},{"en":"all possible","cn":"所有可能的；完全可能的","ex":{"en":"We wish you every success.","cn":"我们祝你万事如意。"}}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"每一;每个","en":"You use every to indicate that you are referring to all the members of a group or all the parts of something and not only some of them.","ex":{"en":"Every village has a green, a church, a pub and a manor house","cn":"每个村庄都有一片绿地、一座教堂、一间酒馆和一座庄园宅第。"}},{"pos":"DET 限定词","cn":"（表示发生频率）每隔，每","en":"You use every in order to say how often something happens or to indicate that something happens at regular intervals.","ex":{"en":"We were made to attend meetings every day","cn":"我们每天都得参加会议。"}},{"pos":"DET 限定词","cn":"每…之中","en":"You use every in front of a number when you are saying what proportion of people or things something happens to or applies to.","ex":{"en":"Two out of every three Britons already own a video recorder","cn":"每3个英国人中就有两个已经有了录像机。"}},{"pos":"DET 限定词","cn":"（用于名词前表示强调）充足的，完全的","en":"You can use every before some nouns, for example 'sign', 'effort', 'reason', and 'intention' in order to emphasize what you are saying.","ex":{"en":"The Congressional Budget Office says the federal deficit shows every sign of getting larger","cn":"国会预算办公室说有种种的迹象表明联邦赤字正在增加。"}},{"pos":"ADJ 形容词","cn":"（幻想、愿望、欲望等）所有的，全部的","en":"If you say that someone's every whim, wish, or desire will be satisfied, you are emphasizing that everything they want will happen or be provided.","ex":{"en":"Dozens of servants had catered to his every whim.","cn":"几十个仆人迎合他所有稀奇古怪的念头。"}},{"pos":"PHRASE 短语","cn":"不时;有时；偶尔","en":"You use every in the expressions every now and then ,every now and again ,every once in a while, and every so often in order to indicate that something happens occasionally.","ex":{"en":"Stir the batter every now and then to keep it from separating","cn":"不时搅动面糊，防止其成分散开。"}},{"pos":"PHRASE 短语","cn":"每隔…（天、周、年）;每…（天、周、年）","en":"If something happens every other day or every second day, for example, it happens one day, then does not happen the next day, then happens the day after that, and so on. You can also say that something happens every third week ,every fourth year, and so on.","ex":{"en":"I went home every other week","cn":"我隔周回一趟家。"}},{"pos":"","cn":"","en":"every bit as good as→see: ; every which way→see: ;"}]},"examples":[{"en":"Every one of their CDs has been a hit.","cn":"他们的每一张激光唱片都曾经非常流行。"},{"en":"We enjoyed every minute of our stay.","cn":"我们逗留期间每一分钟都过得很愉快。"}]},"evenings":{"oxford":{"phon":"ˈiːvnɪŋz","pos":"adverb","senses":[{"en":"during the evening","cn":"黄昏；薄暮","ex":{"en":"He works evenings.","cn":"他晚上工作。"}}]},"media":{"uk":"media/uk/evenings__gb_1.mp3","us":"media/us/evenings__us_1.mp3"},"examples":[{"en":"( especially NAmE ) He works evenings.","cn":"他晚上工作。"}]},"everywhere":{"media":{"uk":"media/uk/everywhere__gb_1.mp3","us":"media/us/everywhere__us_1.mp3"},"oxford":{"phon":"ˈevriweə(r)","pos":"adverb, pronoun, conjunction","senses":[{"en":"in, to or at every place; all places","cn":"处处；到处；各个地方；所有地方","ex":{"en":"I've looked everywhere.","cn":"我各处都看过了。"}}]},"collins":{"senses":[{"pos":"ADV-INDEF 不定副词","cn":"处处;四处;各处;到处","en":"You use everywhere to refer to a whole area or to all the places in a particular area.","ex":{"en":"Working people everywhere object to paying taxes","cn":"各地的工薪族都反对缴税。"}},{"pos":"ADV-INDEF 不定副词","cn":"所经之地;所到之处","en":"You use everywhere to refer to all the places that someone goes to.","ex":{"en":"Bradley is still accustomed to travelling everywhere in style","cn":"布拉德利仍然保持着每次出行必派头十足的习惯。"}},{"pos":"ADV-INDEF 不定副词","cn":"（强调范围广）四处，到处","en":"You use everywhere to emphasize that you are talking about a large number of places, or all possible places.","ex":{"en":"I saw her picture everywhere","cn":"我到处都可以看见她的照片。"}},{"pos":"ADV-INDEF 不定副词","cn":"遍地；到处","en":"If you say that someone or something is everywhere, you mean that they are present in a place in very large numbers.","ex":{"en":"There were cartons of cigarettes everywhere","cn":"到处都是香烟盒。"}}]},"examples":[{"en":"We'll have to eat here — everywhere else is full.","cn":"我们只好在这儿吃饭了，其他地方都客满。"},{"en":"Everywhere we went was full of tourists.","cn":"我们所到之处游客人头攒动。"}]},"everyday":{"media":{"uk":"media/uk/everyday__gb_1.mp3","us":"media/us/everyday__us_1.mp3"},"oxford":{"phon":"ˈevrideɪ","pos":"adjective","senses":[{"en":"used or happening every day or regularly; ordinary","cn":"每天的；每日发生的；日常的","ex":{"en":"Change is a part of everyday life in business.","cn":"在生意上，变化是家常便饭。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"每天（发生）的;平常的;普通的","en":"You use everyday to describe something which happens or is used every day, or forms a regular and basic part of your life, so it is not especially interesting or unusual.","ex":{"en":"In the course of my everyday life, I had very little contact with teenagers.","cn":"在我的日常生活中，我很少和青少年打交道。"}}]},"examples":[{"en":"The Internet has become part of everyday life.","cn":"互联网已成为日常生活的一部分。"},{"en":"a small dictionary for everyday use","cn":"常用小词典"}]},"evidence":{"media":{"uk":"media/uk/evidence__gb_1.mp3","us":"media/us/evidence__us_1.mp3"},"oxford":{"phon":"ˈevɪdəns","pos":"noun","senses":[{"en":"the facts, signs or objects that make you believe that something is true","cn":"根据；证明；证据","g":"[uncountable]","lab":"specialist","ex":{"en":"Researchers have found clear scientific evidence of a link between exposure to sun and skin cancer.","cn":"研究人员发现了明确的科学证据，证明日光暴晒与皮肤癌之间有关联。"}},{"en":"the information that is used in court to try to prove something","cn":"（法庭上的）证据，证词，人证，物证","g":"[uncountable]","lab":"especially North American English","ex":{"en":"I was asked to give evidence (= to say what I knew, describe what I had seen, etc.) at the trial.","cn":"我被要求审讯时出庭作证。"}},{"en":"to prove or show something; to be evidence of something","cn":"证明；表明；作为…的证据","ex":{"en":"The legal profession is still a largely male world, as evidenced by the small number of women judges.","cn":"法律界在很大程度上仍然是男人的世界，这一点从女法官屈指可数即可得到证实。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"证据;佐证；根据","en":"Evidence is anything that you see, experience, read, or are told that causes you to believe that something is true or has really happened.","ex":{"en":"Ganley said he'd seen no evidence of widespread fraud","cn":"甘利说他没有看见诈骗泛滥的证据。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（法庭上的）证据，证物，证词","en":"Evidence is the information which is used in a court of law to try to prove something. Evidence is obtained from documents, objects, or witnesses.","ex":{"en":"The evidence against him was purely circumstantial.","cn":"对他不利的这项证据完全是间接证据。"}},{"pos":"PHRASE 短语","cn":"（在法庭上）提供证据，作证","en":"If you give evidence in a court of law or an official enquiry, you officially say what you know about people or events, or describe an occasion at which you were present.","ex":{"en":"The forensic scientists who carried out the original tests will be called to give evidence","cn":"进行最初化验的法医学家将被传唤到庭作证。"}},{"pos":"VERB 动词","cn":"证明;表明;显示","en":"If a particular feeling, ability, or attitude is evidenced by something or someone, it is seen or felt.","ex":{"en":"He's wise in other ways too, as evidenced by his reason for switching from tennis to golf","cn":"他在其他方面同样明智，这一点可以从他不打网球改打高尔夫的理由中得到证明。"}},{"pos":"PHRASE 短语","cn":"显眼;显而易见","en":"If someone or something is in evidence, they are present and can be clearly seen.","ex":{"en":"Few soldiers were in evidence","cn":"没看见几个士兵。"}}]},"examples":[{"en":"The legal profession is still a largely male world, as evidenced by the small number of women judges.","cn":"法律界在很大程度上仍然是男人的世界，这一点从女法官的人数屈指可数即可得到证实。"},{"en":"On the evidence of their recent matches, it is unlikely the Spanish team will win the cup.","cn":"从西班牙队最近的比赛情况看，他们不太可能夺冠。"}]},"evening":{"media":{"uk":"media/uk/evening__gb_1.mp3","us":"media/us/evening__us_1.mp3"},"oxford":{"phon":"ˈiːvnɪŋ","pos":"noun","senses":[{"en":"the part of the day between the afternoon and the time you go to bed","cn":"晚上；傍晚","g":"[countable, uncountable]","ex":{"en":"Remember to call me this evening.","cn":"今晚记得给我打电话。"}},{"en":"an event of a particular type happening in the evening","cn":"晚会；晚间活动","g":"[countable]","ex":{"en":"a musical evening at school (= when music is performed)","cn":"学校的音乐晚会"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"傍晚;晚上","en":"The evening is the part of each day between the end of the afternoon and the time when you go to bed.","ex":{"en":"All he did that evening was sit around the flat","cn":"那天晚上他一直在公寓里无所事事地坐着。"}}]},"examples":[{"en":"She's going to her sister's for the evening.","cn":"她打算晚上到姐姐家去。"},{"en":"I'll see you tomorrow evening.","cn":"我明天晚上来看你。"}]},"everyone":{"media":{"uk":"media/uk/everyone__gb_1.mp3","us":"media/us/everyone__us_1.mp3"},"oxford":{"phon":"ˈevriwʌn","pos":"pronoun","senses":[{"en":"every person; all people","cn":"每人；人人；所有人","lab":"formal","ex":{"en":"Everyone cheered and clapped.","cn":"人人都鼓掌欢呼。"}}]},"collins":{"senses":[{"pos":"PRON-INDEF 不定代词","cn":"（某个群体中的）每个人，所有人","en":"You use everyone or everybody to refer to all the people in a particular group.","ex":{"en":"Everyone in the street was shocked when they heard the news","cn":"听到那条消息，街上所有的人都震惊了。"}},{"pos":"PRON-INDEF 不定代词","cn":"所有人;人们","en":"You use everyone or everybody to refer to all people.","ex":{"en":"Everyone feels like a failure at times","cn":"人们有时会觉得自己是个失败者。"}}]},"examples":[{"en":"The teacher commented on everyone's work.","cn":"老师对每个人的作业都给了评语。"},{"en":"The police questioned everyone in the room.","cn":"警方盘问了房间里的每一个人。"}]},"evidently":{"media":{"uk":"media/uk/evidently__gb_1.mp3","us":"media/us/evidently__us_1.mp3"},"oxford":{"phon":"ˈevɪdəntli","pos":"adverb","senses":[{"en":"clearly; that can be seen or understood easily","cn":"明显地；显然地","ex":{"en":"She walked slowly down the road, evidently in pain.","cn":"她沿路慢慢地走着，显然很痛苦。"}},{"en":"according to what people say","cn":"据说","ex":{"en":"Evidently, she had nothing to do with the whole affair.","cn":"据说，她与整件事情毫无关系。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"毫无疑问地;明显地","en":"You use evidently to say that something is obviously true, for example because you have seen evidence of it yourself.","ex":{"en":"The man wore a bathrobe and had evidently just come from the bathroom","cn":"那个男子穿着浴袍，显然是刚刚从浴室出来。"}},{"pos":"ADV-GRADED 副词","cn":"显然地（但不十分确定）；据说","en":"You use evidently to show that you think something is true or have been told something is true, but that you are not sure, because you do not have enough information or proof.","ex":{"en":"From childhood, he was evidently at once rebellious and precocious","cn":"从儿时起，他就明显地既叛逆又早熟。"}},{"pos":"ADV-GRADED 副词","cn":"（用于引出陈述或观点，强调其真实性或正确性）显然，肯定","en":"You can use evidently to introduce a statement or opinion and to emphasize that you feel that it is true or correct.","ex":{"en":"Quite evidently, it has nothing to do with social background.","cn":"很显然这与社会背景没有任何关系。"}}]},"examples":[{"en":"‘I'm afraid I couldn't finish the work last night.’ ‘Evidently not.’ “","cn":"对不起，昨天晚上我没能完成工作。” “显然完不成。”"},{"en":"She walked slowly down the road, evidently in pain.","cn":"她沿路慢慢地走着，显然很痛苦。"}]},"evince":{"media":{"uk":"media/uk/evince__gb_1.mp3","us":"media/us/evince__us_1.mp3"},"oxford":{"phon":"ɪˈvɪns","pos":"verb","senses":[{"en":"to show clearly that you have a feeling or quality","cn":"表明，表现，显示（感情或品质）","ex":{"en":"He evinced a strong desire to be reconciled with his family.","cn":"他表现出与家人和好的强烈愿望。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（经常间接地）表明，显示","en":"If someone or something evinces a particular feeling or quality, they show that feeling or quality, often indirectly.","ex":{"en":"The entire production evinces authenticity and a real respect for the subject matter","cn":"整部作品表现出真实性以及对主题的真正尊重。"}}]},"examples":[{"en":"He evinced a strong desire to be reconciled with his family.","cn":"他表现出与家人和好的强烈愿望。"},{"en":"She evinced no surprise at seeing them together.","cn":"看到他们在一起﹐她没有表露出惊讶。"}]},"even":{"media":{"uk":"media/uk/even__gb_1.mp3","us":"media/us/even__us_1.mp3"},"oxford":{"phon":"ˈiːvn","pos":"adverb","senses":[{"en":"used to emphasize something unexpected or surprising","cn":"（强调出乎意料）甚至，连，即使","ex":{"en":"She didn't even call to say she wasn't coming.","cn":"她甚至没打电话来说一声她不来了。"}},{"en":"used when you are comparing things, to make the comparison stronger","cn":"（用以加强比较）甚至更，愈加，还","ex":{"en":"You know even less about it than I do.","cn":"你对此事的了解甚至还不如我。"}},{"en":"used to introduce a more exact description of somebody/something","cn":"（引出更精确的说法）甚至可以说，其实，实际上","ex":{"en":"It's an unattractive building, ugly even.","cn":"这栋建筑毫不美观，甚至可以说难看。"}},{"en":"that can be divided exactly by two","cn":"双数的；偶数的","sc":"numbers","ex":{"en":"4, 6, 8 and 10 are all even numbers.","cn":"4、6、8、10 都是偶数。"},"pos":"adjective"},{"en":"equal or the same for each person, team, place, etc.","cn":"相等的；均等的","sc":"equal","ex":{"en":"Our scores are now even.","cn":"我们的比分现在相等。"},"pos":"adjective"},{"en":"equally balanced or of an equal standard","cn":"均衡的；不相上下的；同一水平的","sc":"equal","ex":{"en":"an even contest","cn":"势均力敌的竞赛"},"pos":"adjective"},{"en":"not changing very much in amount, speed, etc.","cn":"（数量、速度等）变化不大的，均匀的，平稳的","sc":"not changing","ex":{"en":"Children do not learn at an even pace.","cn":"孩子学东西有快有慢。"},"pos":"adjective"},{"en":"smooth, level and flat","cn":"平滑的；平的；平坦的","sc":"smooth/level","ex":{"en":"You need an even surface to work on.","cn":"你需要有个平面在上面工作。"},"pos":"adjective"},{"en":"equally spaced and the same size","cn":"匀称的；均匀的；同样大小的","sc":"same size","ex":{"en":"even features/teeth","cn":"匀称的面容；整齐的牙齿"},"pos":"adjective"},{"en":"calm; not changing or becoming upset","cn":"镇静的；稳重的；平和的，温和的","sc":"calm","ex":{"en":"She has a very even temperament.","cn":"她的性情非常平和。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"甚至;连；即使","en":"You use even to suggest that what comes just after or just before it in the sentence is rather surprising.","ex":{"en":"He kept calling me for years, even after he got married","cn":"多年来他一直打电话给我，甚至是在他结婚以后。"}},{"pos":"ADV 副词","cn":"（与形容词、副词的比较级连用）更加，愈发","en":"You use even with comparative adjectives and adverbs to emphasize a quality that someone or something has.","ex":{"en":"It was on television that he made an even stronger impact as an interviewer","cn":"作为采访者，是电视让他产生了更大的影响。"}},{"pos":"PHR-CONJ-SUBORD","cn":"即使；尽管；纵然","en":"You use even if or even though to indicate that a particular fact does not make the rest of your statement untrue.","ex":{"en":"Cynthia is not ashamed of what she does, even if she ends up doing something wrong","cn":"辛西娅不为自己的所作所为感到羞愧，即使最终证明她所做的是错误的。"}},{"pos":"PHR-CONJ-SUBORD","cn":"恰巧在…时候;正当","en":"If one thing happens even as something else happens, they both happen at exactly the same time.","ex":{"en":"Even as she said this, she knew it was not quite true","cn":"就在她说这个的时候，她知道自己说的并非全是真的。"}},{"pos":"PHRASE 短语","cn":"即便如此;尽管这样","en":"You use even so to introduce a surprising fact which relates to what you have just said.","ex":{"en":"The bus was only half full. Even so, a young man asked Nina if the seat next to her was taken","cn":"公共汽车上只坐满了一半。尽管如此，一个年轻男子还是问尼娜她旁边的座位有没有人坐。"}},{"pos":"PHRASE 短语","cn":"尽管那样;即使那样","en":"You use even then to say that something is the case in spite of what has just been stated or whatever the circumstances may be.","ex":{"en":"Peace could come only gradually, in carefully measured steps. Even then, it sounds almost impossible to achieve","cn":"和平只会逐渐到来，而且每一步都走得小心翼翼。即使那样，要实现和平听起来仍几乎不可能。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不变的;恒定的","en":"An even measurement or rate stays at about the same level.","ex":{"en":"How important is it to have an even temperature when you're working?","cn":"工作时周围环境温度恒定有多么重要呢？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平坦的;光滑的","en":"An even surface is smooth and flat.","ex":{"en":"The tables are fitted with a glass top to provide an even surface.","cn":"桌子装了玻璃表面，因此十分平滑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平均的;均等的","en":"If there is an even distribution or division of something, each person, group, or area involved has an equal amount.","ex":{"en":"Divide the dough into 12 even pieces and shape each piece into a ball","cn":"将面团分成12等份，每份揉成球状。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（比赛、竞争等）平衡的，不相上下的，势均力敌的","en":"An even contest or competition is equally balanced between the two sides who are taking part.","ex":{"en":"It was an even game.","cn":"这是一场势均力敌的比赛。"}},{"pos":"ADJ 形容词","cn":"扯平的;互不相欠的","en":"If you are even with someone, you do not owe them anything, such as money or a favour.","ex":{"en":"You don't owe me. I don't owe you. We're even.","cn":"你不欠我，我也不欠你，我们扯平了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心平气和的;平静的","en":"If your voice is even, you are speaking in a very controlled way which makes it difficult for people to tell what your feelings are.","ex":{"en":"My voice surprised me; it was even and emotionless.","cn":"我的声音听起来心平气和、不露一丝感情，这让我自己颇感惊讶。"}},{"pos":"ADJ 形容词","cn":"偶数的;双数的","en":"An even number can be divided exactly by the number two."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（成败机会）各半的，对半的，相等的","en":"If there is an even chance that something will happen, it is no more likely that it will happen than it will not happen.","ex":{"en":"They have a more than even chance of winning the next election","cn":"他们赢得下届选举的机会在五成以上。"}},{"pos":"PHRASE 短语","cn":"收支相抵；不赔不赚","en":"When a company or a persn running a business breaks even, they make neither a profit nor a loss.","ex":{"en":"The airline hopes to break even next year and return to profit the following year","cn":"那家航空公司希望明年实现收支相抵，在随后一年重新盈利。"}},{"pos":"PHRASE 短语","cn":"跟…算账;与…扯平；向…报复","en":"If you say that you are going to get even with someone, you mean that you are going to cause them the same amount of harm or annoyance as they have caused you.","ex":{"en":"I'm going to get even with you for this","cn":"我会跟你算这笔账的。"}},{"pos":"","cn":"","en":"to be on an even keel→see: ;"},{"pos":"","cn":"","en":"相关词组：even out even up"}]},"examples":[{"en":"I've shown him the photographs but even now he won't believe me.","cn":"我把照片给他看了，即便是这样他仍然不相信我。"},{"en":"There are a lot of spelling mistakes; even so, it's quite a good essay.","cn":"尽管有许多拼写错误，它仍不失为一篇佳作。"}]},"evolve":{"media":{"uk":"media/uk/evolve__gb_1.mp3","us":"media/us/evolve__us_1.mp3"},"oxford":{"phon":"ɪˈvɒlv","pos":"verb","senses":[{"en":"to develop gradually, especially from a simple to a more complicated form; to develop something in this way","cn":"（使）逐渐形成，逐步发展，逐渐演变","g":"[intransitive, transitive]","ex":{"en":"The idea evolved from a drawing I discovered in the attic.","cn":"这种想法是从我在阁楼里发现的一幅画得到启发的。"}},{"en":"to develop over time, often many generations, into forms that are better adapted to survive changes in their environment","cn":"进化；演化","g":"[intransitive, transitive]","lab":"biology","ex":{"en":"The three species evolved from a single ancestor.","cn":"这三种生物从同一祖先进化而来。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"进化；演变","en":"When animals or plants evolve, they gradually change and develop into different forms.","ex":{"en":"The bright plumage of many male birds has evolved to attract females","cn":"很多雄鸟进化出鲜艳的羽毛是为了吸引雌鸟。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）逐步发展;（使）演化","en":"If something evolves or you evolve it, it gradually develops over a period of time into something different and usually more advanced.","ex":{"en":"...a tiny airline which eventually evolved into Pakistan International Airlines","cn":"最终发展成巴基斯坦国际航空公司的一家小型航空公司"}}]},"examples":[{"en":"The idea evolved from a drawing I discovered in the attic.","cn":"这种想法是从我在阁楼里发现的一幅画得到启发的。"},{"en":"The company has evolved into a major chemical manufacturer.","cn":"这家公司已逐步发展成一家大型的化工厂。"}]},"evaluation":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a judgment about how good, useful, or successful something is","cn":"评估，评价"}]},"examples":[{"en":"We need to carry out a proper evaluation of the new system.","cn":"我们要对新系统进行合理的评估。","src":"ld"},{"en":"They took some samples of products for evaluation.","cn":"他们抽取了一些产品样本以作评估。","src":"ld"}],"media":{"uk":"media/uk/evaluation__gb_1.mp3","us":"media/us/evaluation__us_1.mp3"},"oxford":{"phon":"ɪˌvæljuˈeɪʃn","pos":"noun","senses":[{"en":"the act of forming an opinion of the amount, value or quality of something after thinking about it carefully","cn":"估计；评价；评估","ex":{"en":"an evaluation of the healthcare system","cn":"对医疗体系的评估"}}]}},"evolution":{"media":{"uk":"media/uk/evolution__gb_1.mp3","us":"media/us/evolution__us_1.mp3"},"oxford":{"phon":"ˌiːvəˈluːʃn","pos":"noun","senses":[{"en":"the slow steady development of plants, animals, etc. during the history of the earth, as they adapt to changes in their environment","cn":"进化","g":"[uncountable]","lab":"biology","ex":{"en":"the evolution of the human species","cn":"人类的进化"}},{"en":"the slow steady development of something","cn":"演变；发展；渐进","g":"[uncountable, countable]","ex":{"en":"In politics Britain has preferred evolution to revolution (= slow steady development to sudden violent change)","cn":"英国在政治上倾向于渐进而不愿革命。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"进化","en":"Evolution is a process of gradual change that takes place over many generations, during which species of animals, plants, or insects slowly change some of their physical characteristics.","ex":{"en":"...the evolution of plants and animals.","cn":"动植物的进化"}},{"pos":"N-VAR 可变名词","cn":"演变;演化;演进;发展","en":"Evolution is a process of gradual development in a particular situation or thing over a period of time.","ex":{"en":"...a crucial period in the evolution of modern physics.","cn":"现代物理学演化过程中的重要时期"}}]},"examples":[{"en":"In politics Britain has preferred evolution to revolution (= gradual development to sudden violent change).","cn":"英国在政治上宁愿渐进而不愿革命。"},{"en":"the evolution of the human species","cn":"人类的进化"}]},"evil":{"media":{"uk":"media/uk/evil__gb_1.mp3","us":"media/us/evil__us_1.mp3"},"oxford":{"phon":"ˈiːvl","pos":"adjective","senses":[{"en":"enjoying harming others; morally bad and cruel","cn":"恶毒的；邪恶的","ex":{"en":"Police described the killer as ‘a desperate and evil man’.","cn":"警方称凶手是“一个绝望而邪恶的人”。"}},{"en":"having a harmful effect on people; morally bad","cn":"有害的；道德败坏的","ex":{"en":"evil deeds","cn":"恶行"}},{"en":"connected with the devil and with what is bad in the world","cn":"恶魔的；罪恶的","ex":{"en":"It was an ancient charm to ward off evil spirits.","cn":"这是古代驱赶邪灵的一种做法。"}},{"en":"extremely unpleasant","cn":"极讨厌的；令人作呕的；使人极不舒服的","ex":{"en":"The rubbish bin was giving off an evil smell.","cn":"垃圾桶里散发着恶臭。"}},{"en":"a force that causes bad things to happen; morally bad behaviour","cn":"邪恶；罪恶；恶行","g":"[uncountable]","ex":{"en":"the eternal struggle between good and evil","cn":"善与恶永不休止的斗争"},"pos":"noun"},{"en":"a bad or harmful thing; the bad effect of something","cn":"害处；坏处；弊端","g":"[countable, usually plural]","ex":{"en":"the evils of drugs/alcohol","cn":"毒品／酒的害处"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恶;罪恶;邪恶","en":"Evil is a powerful force that some people believe to exist, and which causes wicked and bad things to happen.","ex":{"en":"We are still being attacked by the forces of evil","cn":"我们仍在遭受邪恶力量的攻击。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"坏事;恶行","en":"Evil is used to refer to all the wicked and bad things that happen in the world.","ex":{"en":"He could not, after all, stop all the evil in the world.","cn":"毕竟他无法阻止世界上的所有恶行。"}},{"pos":"N-COUNT 可数名词","cn":"祸害;灾难;弊病;不幸","en":"If you refer to an evil, you mean a very unpleasant or harmful situation or activity.","ex":{"en":"Apartheid is even a greater evil","cn":"种族隔离是更大的祸害。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）凶恶的，邪恶的","en":"If you describe someone as evil, you mean that they are very wicked by nature and take pleasure in doing things that harm other people.","ex":{"en":"...the country's most evil terrorists","cn":"该国最邪恶的恐怖分子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"危害社会的；道德败坏的","en":"If you describe something as evil, you mean that you think it causes a great deal of harm to people and is morally bad.","ex":{"en":"After 1760 few Americans refrained from condemning slavery as evil","cn":"1760年后，很多美国人都在谴责奴隶制的社会危害。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受魔鬼影响的;恶魔的;不祥的","en":"If you describe something as evil, you mean that you think it is influenced by the devil.","ex":{"en":"I think this is an evil spirit at work","cn":"我认为这是恶魔在作祟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（气味）难闻的，令人不舒服的","en":"You can describe a very unpleasant smell as evil.","ex":{"en":"Both men were smoking evil-smelling pipes.","cn":"两个男人都在抽着难闻的烟斗。"}},{"pos":"PHRASE 短语","cn":"倒霉的日子/时刻","en":"If someone is putting off the evil day or the evil hour, they have to do something unpleasant and are trying to avoid doing it for as long as possible.","ex":{"en":"You can simply go on putting off the evil day and eventually find yourself smoking as much as ever.","cn":"你当然可以想方设法摆脱，但最后你会发现自己还是像以前一样拼命抽烟。"}},{"pos":"PHRASE 短语","cn":"两害中的较轻者","en":"If you have two choices, but think that they are both bad, you can describe the one which is less bad as the lesser of two evils, or the lesser evil .","ex":{"en":"People voted for him as the lesser of two evils","cn":"人们投票支持他只不过是两害相权取其轻罢了。"}}]},"examples":[{"en":"You cannot pretend there's no evil in the world.","cn":"你不能睁着眼睛瞎说世界上没有罪恶。"},{"en":"the eternal struggle between good and evil","cn":"善与恶永不休止的斗争"}]},"evaluate":{"media":{"uk":"media/uk/evaluate__gb_1.mp3","us":"media/us/evaluate__us_1.mp3"},"oxford":{"phon":"ɪˈvæljueɪt","pos":"verb","senses":[{"en":"to form an opinion of the amount, value or quality of something after thinking about it carefully","cn":"估计；评价；评估","ex":{"en":"The trial will evaluate the effectiveness of the different drugs.","cn":"这个试验将评估不同药物的疗效。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"评估;评价","en":"If you evaluate something or someone, you consider them in order to make a judgment about them, for example about how good or bad they are.","ex":{"en":"They will first send in trained nurses to evaluate the needs of the individual situation","cn":"他们首先会派一些训练有素的护士来评估每个病人的需求。"}}]},"examples":[{"en":"Our research attempts to evaluate the effectiveness of the different drugs.","cn":"我们的研究试图对不同药物的疗效进行评估。"},{"en":"We need to evaluate how well the policy is working.","cn":"我们需要对这一政策产生的效果作出评价。"}]},"evident":{"media":{"uk":"media/uk/evident__gb_1.mp3","us":"media/us/evident__us_1.mp3"},"oxford":{"phon":"ˈevɪdənt","pos":"adjective","senses":[{"en":"clear; easily seen","cn":"清楚的；显而易见的；显然的","ex":{"en":"The orchestra played with evident enjoyment.","cn":"管弦乐队演奏得兴致勃勃。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明显的;显然的;清楚的","en":"If something is evident, you notice it easily and clearly.","ex":{"en":"His footprints were clearly evident in the heavy dust","cn":"厚厚的尘土中他的脚印清晰易见。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"显然的;明显的","en":"You use evident to show that you are certain about a situation or fact and your interpretation of it.","ex":{"en":"It was evident that she had once been a beauty","cn":"显然她曾是个美人儿。"}}]},"examples":[{"en":"The growing interest in history is clearly evident in the number of people visiting museums and country houses.","cn":"从参观博物馆和乡村住宅的人数明显看出人们对历史越来越感兴趣。"},{"en":"It has now become evident to us that a mistake has been made.","cn":"我们现已清楚知道出了差错。"}]},"everybody":{"media":{"uk":"media/uk/everybody__gb_1.mp3","us":"media/us/everybody__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"同everyone","en":"Everybody means the same as everyone ."}]},"examples":[{"en":"Didn't you like it? Everybody else did.","cn":"你不喜欢吗？其他所有人都喜欢。"},{"en":"Have you asked everybody?","cn":"你每个人都问了吗？"}],"oxford":{"phon":"ˈevribɒdi","pos":"pronoun","senses":[{"en":"every person; all people","cn":"每人；人人；所有人","ex":{"en":"Everybody knows Tom.","cn":"人人都认识汤姆。"}}]}},"evoke":{"media":{"uk":"media/uk/evoke__gb_1.mp3","us":"media/us/evoke__us_1.mp3"},"oxford":{"phon":"ɪˈvəʊk","pos":"verb","senses":[{"en":"to bring a feeling, a memory or an image into your mind","cn":"引起，唤起（感情、记忆或形象）","ex":{"en":"The music evoked memories of her youth.","cn":"这乐曲勾起了她对青年时代的回忆。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"唤起;召唤;引起","en":"To evoke a particular memory, idea, emotion, or response means to cause it to occur.","ex":{"en":"...the scene evoking memories of those old movies","cn":"唤起对那些老电影的记忆的场景"}}]},"examples":[{"en":"a brilliant evocation of childhood in the 1940s","cn":"唤起对 20 世纪 40 年代童年生活的美好回忆"},{"en":"The music evoked memories of her youth.","cn":"这乐曲勾起了她对青年时代的回忆。"}]},"ever":{"media":{"uk":"media/uk/ever__gb_1.mp3","us":"media/us/ever__us_1.mp3"},"oxford":{"phon":"ˈevə(r)","pos":"adverb","senses":[{"en":"used in negative sentences and questions, or sentences with if to mean ‘at any time’","cn":"（用于否定句和疑问句，或与 if 连用的句子）在任何时候，从来","lab":"informal","ex":{"en":"Nothing ever happens here.","cn":"这儿从未发生过任何事。"}},{"en":"used for emphasis when you are comparing things","cn":"（进行比较时用以加强语气）以往任何时候，曾经","ex":{"en":"It was raining harder than ever.","cn":"当时下着前所未有的大雨。"}},{"en":"all the time or every time; always","cn":"不断地；总是；始终","lab":"rather formal","ex":{"en":"Paul, ever the optimist, agreed to try again.","cn":"保罗这个一贯的乐观主义者答应再试一次。"}},{"en":"used after when, why, etc. to show that you are surprised or shocked","cn":"（用于 when、why 等之后表示惊讶）究竟，到底","ex":{"en":"Why ever did you agree?","cn":"你究竟为什么要同意？"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（用于否定句和疑问句）在任何时候，从来","en":"Ever means at any time. It is used in questions and negative statements. →see usage note at:","ex":{"en":"I'm not sure I'll ever trust people again","cn":"我不确定自己是否还会再相信任何人。"}},{"pos":"ADV 副词","cn":"（表示惊讶、震惊，尤用于希望别人赞同时）曾否，可曾","en":"You use ever in expressions such as 'did you ever' and 'have you ever' to express surprise or shock at something you have just seen, heard, or experienced, especially when you expect people to agree with you.","ex":{"en":"Have you ever seen anything like it?","cn":"你可曾见过像它这样的东西？"}},{"pos":"ADV 副词","cn":"（用于比较级和最高级后表示强调）以往任何时候，曾经","en":"You use ever after comparatives and superlatives to emphasize the degree to which something is true or when you are comparing a present situation with the past or the future.","ex":{"en":"She's got a great voice and is singing better than ever","cn":"她的嗓音非常好，现在的唱功比以往任何时候都要好。"}},{"pos":"ADV 副词","cn":"一向;向来","en":"You use ever to indicate that a person is showing a particular quality that is typical of them.","ex":{"en":"He was ever careful to check his scripts","cn":"他一向都认真检查剧本。"}},{"pos":"ADV 副词","cn":"越来越;愈发","en":"You use ever to say that something happens more all the time.","ex":{"en":"They grew ever further apart","cn":"他们变得越来越疏远了。"}},{"pos":"ADV 副词","cn":"（用于never后表强调）绝对，一定","en":"You can use ever for emphasis after 'never'.","ex":{"en":"I can never, ever, forgive myself","cn":"我永远无法原谅我自己。"}},{"pos":"ADV 副词","cn":"（用于以why，when，who等开头的疑问句中表示强调）究竟，到底","en":"You use ever in questions beginning with words such as 'why', 'when', and 'who' when you want to emphasize your surprise or shock.","ex":{"en":"Why ever didn't you tell me?","cn":"你究竟为什么不告诉我？"}},{"pos":"PHR-CONJ-SUBORD","cn":"自从;打…以后一直","en":"If something has been the case ever since a particular time, it has been the case all the time from then until now.","ex":{"en":"He's been there ever since you left!","cn":"自从你离开后他就一直在那里！"}},{"pos":"ADV 副词","cn":"（尤用于表示非常感兴趣或感激时）非常，太","en":"You use ever in the expressions ever such and ever so to emphasize that someone or something has a particular quality, especially when you are expressing enthusiasm or gratitude.","ex":{"en":"When I met Derek he was ever such a good dancer","cn":"我认识德里克时，他是个非常出色的舞者。"}},{"pos":"PHRASE 短语","cn":"就会…;总是…","en":"You use the expression all someone ever does when you want to emphasize that they do the same thing all the time, and this annoys you.","ex":{"en":"All she ever does is whinge and complain","cn":"她就会发牢骚抱怨。"}},{"pos":"PHRASE 短语","cn":"一如既往;像往常那样","en":"You say as ever in order to indicate that something or someone's behaviour is not unusual because it is like that all the time or very often.","ex":{"en":"As ever, the meals are primarily fish-based","cn":"像往常一样，饭菜主要是鱼。"}},{"pos":"CONVENTION 惯用语","cn":"（用于书信结尾署名之前）你永远的朋友","en":"You can write 'Yours ever' or 'Ever yours' at the end of a letter before you sign your name, as an affectionate way of ending the letter."},{"pos":"","cn":"","en":"hardly ever→see: ;"}]},"examples":[{"en":"‘Have you ever been to Rome?’ ‘Yes, I have, actually. Not long ago.’ “","cn":"你去过罗马吗？” “是的，我确实去过，就在不久前。”"},{"en":"‘Have you ever thought of changing your job?’ ‘No, never/No I haven't.’ “","cn":"你想过换一下工作吗？” “没有，从未想过。”"}]},"evolutionary":{"media":{"uk":"media/uk/evolutionary__gb_1.mp3","us":"media/us/evolutionary__us_1.mp3"},"oxford":{"phon":"ˌiːvəˈluːʃənri","pos":"adjective","senses":[{"en":"connected with evolution; connected with slow steady development and change","cn":"进化的；演变的；逐渐发展的","ex":{"en":"evolutionary theory","cn":"进化论"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"进化的;进化论的；发展的","en":"Evolutionary means relating to a process of gradual change and development.","ex":{"en":"...an evolutionary process.","cn":"进化过程"}}]},"examples":[{"en":"evolutionary change","cn":"逐渐演变"},{"en":"evolutionary theory","cn":"进化论"}]},"events":{"oxford":{"phon":"ɪˈvent","pos":"noun","senses":[{"en":"a thing that happens, especially sth important","cn":"发生的事情；（尤指）重要事情，大事"},{"en":"a planned public or social occasion","cn":"公开活动；社交场合"}]}},"evaluations":{"oxford":{"phon":"ɪˈvæljueɪt","pos":"verb","senses":[{"en":"to form an opinion of the amount, value or quality of sth after thinking about it carefully","cn":"估计；评价；评估"}]}},"event":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"事件;（尤指）特殊事件，重大事件","en":"An event is something that happens, especially when it is unusual or important. You can use events to describe all the things that are happening in a particular situation.","ex":{"en":"...the events of Black Wednesday","cn":"“黑色星期三”事件"}},{"pos":"N-COUNT 可数名词","cn":"（社交聚会、体育比赛等有计划、有组织的）活动","en":"An event is a planned and organized occasion, for example a social gathering or a sports match.","ex":{"en":"The cross-country section of the three-day event was held here yesterday.","cn":"3日比赛中的越野项目昨天在这里举行。"}},{"pos":"N-COUNT 可数名词","cn":"（体育比赛等的）比赛项目","en":"An event is one of the races or competitions that are part of an organized occasion such as a sports meeting.","ex":{"en":"A solo piper opens Aberdeen Highland Games at 10am and the main events start at 1pm.","cn":"上午10点，一位风笛独奏家揭开了阿伯丁高地运动会的序幕，下午1点主要比赛项目开始。"}},{"pos":"PHRASE 短语","cn":"万一发生…；如果是那样子的话；假若…","en":"You use in the event of ,in the event that, and in that event when you are talking about a possible future situation, especially when you are planning what to do if it occurs.","ex":{"en":"The bank has agreed to give an immediate refund in the unlikely event of an error being made","cn":"万一出现错误——虽然这种几率微乎其微，银行同意立即退款。"}},{"pos":"PHRASE 短语","cn":"无论如何;不管怎样","en":"You say in any event after you have been discussing a situation, in order to indicate that what you are saying is true or possible, in spite of anything that has happened or may happen.","ex":{"en":"In any event, the bowling alley restaurant proved quite acceptable.","cn":"无论如何，那个保龄球场的餐厅证明还是很不错的。"}},{"pos":"PHRASE 短语","cn":"结果;到头来","en":"You say in the event after you have been discussing what could have happened in a particular situation, in order to indicate that you are now describing what actually did happen.","ex":{"en":"'Don't underestimate us', Norman Willis warned last year. There was, in the event, little danger of that.","cn":"“别低估了我们，”诺曼·威利斯去年警告说。结果，什么事也没有。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens, especially something important, interesting, or unusual 〔","cn":"尤指重要﹑有趣或不寻常的〕事件"},{"en":"something that happens – used especially when saying how often something happens","cn":"事件〔尤在说明其频繁与否时使用〕"},{"en":"something that happens, especially something that is unusual or unpleasant, or something that is one of several events","cn":"发生的事情〔尤指不寻常﹑不愉快的事或若干事件中的一起〕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An event is something that happens, or might happen. In the event that you get stuck in traffic, the wedding will continue. It is too important an event to wait even for someone as important as you."}]},"collocations":{"phrases":["ADJ. big, great, historic, important, key, main, major, momentous, significant Tonight's programme looks back at the main events of the year","VERB + EVENT witness When the ship finally reached land, only a few of the crew were left to witness the event. | record We had a huge party","EVENT + VERB happen, occur, take place, unfold TV viewers watched in horror as events unfolded. | lead to sth These events quickly led to co","PHRASES a chain/sequence/series of events, the course of events Would it have been possible to change the course of events? 2 planned social","ADJ. big, important, main, major, special | popular | prestigious The Birmingham meeting is one of the most prestigious events in the racing","VERB + EVENT enter (for), take part in A record number of teams have entered the event. | win","EVENT + VERB take place The team events will take place later this week.","PREP. in an/the ~ African runners swept the medals in the distance events."]},"media":{"uk":"media/ldoce/hwd/bre/1/event0205.mp3","us":"media/ldoce/hwd/ame/4/event.mp3"},"examples":[{"en":"I got very nervous about the exam, but in the event, I needn't have worried; it was really easy.","cn":"我对考试提心吊胆，但其实我本不必担心，这次考试的确很容易。"},{"en":"The decisions we take now may influence the course of events (= the way things happen) in the future.","cn":"我们现在作出的决定可能会对未来事情的发展产生影响。"}],"oxford":{"phon":"ɪˈvent","pos":"noun","senses":[{"en":"a thing that happens, especially something important","cn":"发生的事情；（尤指）重要事情，大事","lab":"medical","ex":{"en":"recent/current/world events","cn":"近期事件；时事；世界大事"}},{"en":"a planned public or social occasion","cn":"公开活动；社交场合","ex":{"en":"Is the city ready to host such a major sporting event?","cn":"这个城市准备好举办这样一个大型的体育盛会了吗？"}},{"en":"one of the races or competitions in a sports programme","cn":"（体育运动的）比赛项目","ex":{"en":"The 800 metres is the fourth event of the afternoon.","cn":"800 米赛是下午的第四项比赛。"}}]}},"evacuate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"疏散;使撤离;转移","en":"To evacuate someone means to send them to a place of safety, away from a dangerous building, town, or area.","ex":{"en":"They were planning to evacuate the seventy American officials still in the country","cn":"他们正计划转移仍滞留在该国的70名美国官员。"}},{"pos":"VERB 动词","cn":"（尤指因为危险而）撤离，撤出，搬出","en":"If people evacuate a place, they move out of it for a period of time, especially because it is dangerous.","ex":{"en":"The fire is threatening about sixty homes, and residents have evacuated the area","cn":"大火正威胁着大约60户人家，居民已经从该地区撤离。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to empty a place by asking the people in it to leave","cn":""},{"en":"if the police or the authorities evacuate a place, they order everyone in it to leave, especially because it may be dangerous","cn":""},{"en":"to send people away from a dangerous place to a safe place","cn":"撤离﹐撤出"}]},"vocab":{"pos":"1 v 2 v 3 v","senses":[{"en":"To evacuate is to flee, like how people leave an area when a hurricane is coming. It also means to empty something completely."}]},"collocations":{"phrases":["ADV. safely","VERB + EVACUATE help (to) to provide aircraft to help evacuate refugees","PREP. from Helicopters were used to evacuate people from their homes. | to The man has now been safely evacuated to the mainland."]},"media":{"uk":"media/ldoce/hwd/bre/3/evacuate0205.mp3","us":"media/ldoce/hwd/ame/d/evacuate.mp3"},"examples":[{"en":"Children were evacuated from London to escape the bombing.","cn":"为躲避轰炸，孩子们都撤离了伦敦。"},{"en":"Employees were urged to evacuate their offices immediately.","cn":"已敦促各雇员立即从办公室撤出。"}],"oxford":{"phon":"ɪˈvækjueɪt","pos":"verb","senses":[{"en":"to move people from a place of danger to a safer place","cn":"（把人从危险的地方）疏散，转移，撤离","g":"[transitive]","ex":{"en":"Police evacuated nearby buildings.","cn":"警方已将附近大楼的居民疏散。"}},{"en":"to move out of a place because of danger, and leave the place empty","cn":"（从危险的地方）撤出，搬出，撤空","g":"[transitive, intransitive]","ex":{"en":"Employees were urged to evacuate their offices immediately.","cn":"已敦促各雇员立即从办公室撤出。"}},{"en":"to empty your bowels","cn":"排空（胃肠）；排泄（粪便）","g":"[transitive]","lab":"formal"}]}},"eviction":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"驱逐;驱赶","en":"Eviction is the act or process of officially forcing someone to leave a house or piece of land.","ex":{"en":"He was facing eviction, along with his wife and family","cn":"他和妻子、家人正面临着被驱逐。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to force someone to leave the place where they live","cn":""},{"en":"to legally force someone to leave the house where they are living, especially because they should not be there or they have not paid their rent","cn":""},{"en":"to tell someone officially that they must leave the place they are renting by a particular date","cn":""}]},"collocations":{"phrases":["ADJ. illegal, unlawful He claimed damages for unlawful eviction. | forcible","VERB + EVICTION be threatened with, face | resist","EVICTION + NOUN notice, order, warrant","PREP. ~ from They are facing eviction from their home."]},"media":{"uk":"media/ldoce/hwd/bre/6/evict0205.mp3","us":"media/ldoce/hwd/ame/e/evict.mp3"},"examples":[{"en":"to face eviction from your home","cn":"面临着被赶出家门"}],"oxford":{"phon":"ɪˈvɪkʃn","pos":"noun","senses":[{"en":"the act of forcing somebody to leave a house or land, especially when you have the legal right to do so","cn":"（尤指依法从房屋或土地上）驱逐，赶出，逐出","ex":{"en":"to face eviction from your home","cn":"面临着被赶出家"}}]}},"evade":{"collins":{"senses":[{"pos":"VERB 动词","cn":"规避;逃避","en":"If you evade something, you find a way of not doing something that you really ought to do.","ex":{"en":"By his own admission, he evaded taxes as a Florida real-estate speculator","cn":"他亲口承认自己在佛罗里达从事房地产投机生意时逃过税。"}},{"pos":"VERB 动词","cn":"回避，避开（问题、话题等）","en":"If you evade a question or a topic, you avoid talking about it or dealing with it.","ex":{"en":"Mr Portillo denied he was evading the question","cn":"波蒂略先生否认自己正在回避那个问题。"}},{"pos":"VERB 动词","cn":"躲避;避开","en":"If you evade someone or something, you move so that you can avoid meeting them or avoid being touched or hit.","ex":{"en":"Under the pretence of lighting a candle, she evades him and disappears","cn":"她假装点蜡烛，避开他消失了。"}},{"pos":"VERB 动词","cn":"（成功、光荣、爱情等）与…无缘","en":"If something such as success, glory, or love evades you, you do not manage to have it.","ex":{"en":"Happiness, which had been so elusive in Henry's life, still evaded him","cn":"亨利生活中过去一直难以捕捉的幸福仍旧与他无缘。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to find a way of not doing something that you should do","cn":""},{"en":"to avoid doing something you should do or something you promised to do. Get out of is more common than avoid in everyday spoken English","cn":""},{"en":"to avoid doing something you should do by making up excuses – used to show disapproval","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you evade something, you escape it. You could evade a police chase by slipping into a secret alley, or you could evade your mother's questions about the missing cookies by slipping into another topic."}]},"collocations":{"phrases":["ADV. narrowly They narrowly evaded a police car which was approaching. | successfully","VERB + EVADE attempt to, try to | manage to He managed to evade capture and escaped over the border. 2 avoid dealing with sth","ADV. simply Her response was simply to evade the problem altogether. | carefully, skilfully | easily Responsibility could not be so easily e","VERB + EVADE attempt to, try to"]},"media":{"uk":"media/ldoce/hwd/bre/1/evade0205.mp3","us":"media/ldoce/hwd/ame/4/evade.mp3"},"examples":[{"en":"She is trying to evade all responsibility for her behaviour.","cn":"她在试图逃避应为自己的行为承担的所有责任。"},{"en":"Come on, don't you think you're evading the issue?","cn":"得了吧，你不认为你是在回避这个问题吗？"}],"oxford":{"phon":"ɪˈveɪd","pos":"verb","senses":[{"en":"to escape from somebody/something or avoid meeting somebody","cn":"逃脱；躲开；躲避","ex":{"en":"For two weeks they evaded the press.","cn":"他们有两周一直避而不见记者。"}},{"en":"to find a way of not doing something, especially something that legally or morally you should do","cn":"逃避，规避（尤指法律或道德责任）","ex":{"en":"The defendant had tried to evade payment of taxes.","cn":"被告曾试图逃税。"}},{"en":"to avoid dealing with or talking about something","cn":"回避，避开（处理或谈论某事）","ex":{"en":"Come on, don't you think you're evading the issue?","cn":"得了吧，你不认为你是在回避这个问题吗？"}},{"en":"to not come or happen to somebody","cn":"使达不到；未发生在（某人）身上","lab":"formal","ex":{"en":"The answer evaded him (= he could not think of it).","cn":"他答不上来。"}}]}},"everest":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the highest mountain in the world in the Himalayas, on the border between Tibet and Nepal","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/p028-000004746.mp3","us":"media/ldoce/hwd/ame/4/p028-000004746.mp3"}},"eve":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"前夕;前一天；前一段时间","en":"The eve of a particular event or occasion is the day before it, or the period of time just before it.","ex":{"en":"...on the eve of his 27th birthday.","cn":"在他27岁生日前一天"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"before you do something or before an event happens","cn":""},{"en":"if you do something beforehand or ahead of time , you do it before you do something else, especially to make the situation easier","cn":""},{"en":"before you do something else","cn":""}]},"collocations":{"phrases":["ADJ. Christmas, Midsummer's, New Year's","PREP. on the ~ of opinion polls published on the eve of the election"]},"media":{"uk":"media/ldoce/hwd/bre/9/eve0205.mp3","us":"media/ldoce/hwd/ame/d/eve1.mp3"},"examples":[{"en":"on the eve of the election","cn":"在选举前夕"},{"en":"a New Year's Eve party (= on 31 December)","cn":"除夕晚会"}],"oxford":{"phon":"iːv","pos":"noun","senses":[{"en":"the day or evening before an event, especially a religious festival or holiday","cn":"（尤指宗教节假日的）前夜，前夕","ex":{"en":"Christmas Eve (= 24 December)","cn":"圣诞前夕（12 月 24 日）"}},{"en":"evening","cn":"傍晚；黄昏","lab":"old use or literary","ex":{"en":"one midsummer’s eve","cn":"一个仲夏夜"}},{"en":"a first name for girls","cn":"伊芙（女子名）","pos":""}]}},"evict":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（通常因为违法或毁约而）驱逐，赶出","en":"If someone is evicted from the place where they are living, they are forced to leave it, usually because they have broken a law or contract.","ex":{"en":"They were evicted from their apartment after their mother became addicted to drugs","cn":"他们的母亲吸毒上瘾后，他们被从公寓里赶了出来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to force someone to leave the place where they live","cn":""},{"en":"to legally force someone to leave the house where they are living, especially because they should not be there or they have not paid their rent","cn":""},{"en":"to tell someone officially that they must leave the place they are renting by a particular date","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Use the verb evict to say that a tenant is being forced to move out of his home, usually through legal action. If you don't pay your rent, eventually your landlord will evict you."}]},"collocations":{"phrases":["ADV. forcibly | unlawfully","VERB + EVICT seek to, try to","PREP. from They were forcibly evicted from their home."]},"media":{"uk":"media/ldoce/hwd/bre/6/evict0205.mp3","us":"media/ldoce/hwd/ame/e/evict.mp3"},"examples":[{"en":"A number of tenants have been evicted for not paying the rent.","cn":"一些房客因不付房租被赶了出来。"},{"en":"to face eviction from your home","cn":"面临着被赶出家门"}],"oxford":{"phon":"ɪˈvɪkt","pos":"verb","senses":[{"en":"to force somebody to leave a house or land, especially when you have the legal right to do so","cn":"（尤指依法从房屋或土地上）驱逐，赶出，逐出","ex":{"en":"A number of tenants have been evicted for not paying the rent.","cn":"一些房客因没付房租被赶了出来。"}}]}}});
